def svg(w,h,body):
 return f'<svg xmlns="http://www.w3.org/2000/svg" width="{w}" height="{h}" viewBox="0 0 {w} {h}">{body}</svg>'
def mark(size,scale,mono=False,thick=False):
 p=GEOMETRY['paths'];cx,cy=GEOMETRY['center']
 tr=f'translate({size/2:g} {size/2:g}) scale({scale:.8f}) translate({-cx:g} {-cy:g})'
 if mono:
  d=' '.join([p['card'],p['spade'],*p['eyes']]);body=f'<path fill="#FFFFFF" fill-rule="evenodd" d="{d}"/>'
 else:
  body=f'<path fill="{IVORY}" d="{p["card"]}"/>'
  body+=f'<path fill="{GREEN}"'+(f' stroke="{GREEN}" stroke-width="8" stroke-linejoin="round"' if thick else '')+f' d="{p["spade"]}"/>'
  for d in p['eyes']:
   body+=f'<path fill="{DARK}"'+(f' stroke="{DARK}" stroke-width="12" stroke-linejoin="round"' if thick else '')+f' d="{d}"/>'
 return f'<g transform="{tr}">{body}</g>'
def main():
 args=[a for a in sys.argv[1:] if a!='--inkscape'];out=Path(args[0] if args else Path(__file__).parent);out.mkdir(parents=True,exist_ok=True);src=out/'sources';src.mkdir(exist_ok=True)
